const items = $('Filter Files Present on Remote').all().map(item => item.json);
const webhookUrl = 'http://10.20.0.30:5678/webhook/3883600a-ff60-4431-bcef-16e71ff99971';
const timestamp = new Date().getTime();
const batchHasUmi = items.every(i => String(i.HAS_UMI).trim() === 'true');

const AWS_CONC = 32;        // test edilen
const AWS_CHUNK = '16MB';   // test edilen

const sampleBlocks = items.map((item) => {
  const files = item.LOCAL_FILES.split('\n').map(f => f.trim()).filter(Boolean);
  const encodedJson = Buffer.from(JSON.stringify({ ...item, BATCH_HAS_UMI: batchHasUmi })).toString('base64');

  const cpLines = files.map((f) => {
    const fileName = f.substring(f.lastIndexOf('/') + 1);
    return `  upload_one "${f}" "s3://$BUCKET/\${PREFIX}${item.SAMPLE_ID}/${fileName}" & pids+=($!)`;
  }).join('\n');

  return [
`echo "[$(date '+%F %T')] === ${item.SAMPLE_ID} START ==="`,
`CREDS=$("$ICAV2" projectdata temporarycredentials /input_folder/ --project-id "${item.PROJECT_ID}" -o json)`,
`AK=$(echo "$CREDS" | jq -r .awsTempCredentials.accessKey)`,
`SK=$(echo "$CREDS" | jq -r .awsTempCredentials.secretKey)`,
`ST=$(echo "$CREDS" | jq -r .awsTempCredentials.sessionToken)`,
`BUCKET=$(echo "$CREDS" | jq -r .awsTempCredentials.bucket)`,
`PREFIX=$(echo "$CREDS" | jq -r .awsTempCredentials.objectPrefix)`,
`WD=$(mktemp -d)`,
`printf '[awsup]\\naws_access_key_id=%s\\naws_secret_access_key=%s\\naws_session_token=%s\\n' "$AK" "$SK" "$ST" > "$WD/creds"`,
`printf '[profile awsup]\\nregion=us-east-1\\ns3=\\n    max_concurrent_requests=${AWS_CONC}\\n    multipart_threshold=64MB\\n    multipart_chunksize=${AWS_CHUNK}\\n' > "$WD/config"`,
`export AWS_SHARED_CREDENTIALS_FILE="$WD/creds" AWS_CONFIG_FILE="$WD/config"`,
`pids=()`,
cpLines,
`ok=1; for p in "\${pids[@]}"; do wait $p || ok=0; done`,
`unset AWS_SHARED_CREDENTIALS_FILE AWS_CONFIG_FILE; rm -rf "$WD"`,
`if [ "$ok" = "1" ]; then`,
`  sleep 60`,
`  echo "[$(date '+%F %T')] Sending webhook for ${item.SAMPLE_ID}"`,
`  echo '${encodedJson}' | base64 -d | curl -X POST "${webhookUrl}" -H "Content-Type: application/json" -d @- --max-time 30`,
`else`,
`  echo "[$(date '+%F %T')] UPLOAD FAILED for ${item.SAMPLE_ID} - webhook skipped"`,
`fi`,
  ].join('\n');
}).join('\n');

const logFile = `/tmp/upload_webhook_batch_${timestamp}.log`;
const scriptFile = `/tmp/awsup_${timestamp}.sh`;

const script = [
`#!/bin/bash`,
`AWS=~/bin/aws`,
`ICAV2=~/bin/icav2`,
`upload_one(){ src="$1"; dst="$2"; for a in 1 2 3; do "$AWS" s3 cp "$src" "$dst" --profile awsup && return 0; echo "retry $a: $src"; sleep $((a*10)); done; return 1; }`,
sampleBlocks,
`echo "[$(date '+%F %T')] ALL DONE"`,
].join('\n');

const command = `cat > ${scriptFile} <<'AWSEOF'\n${script}\nAWSEOF\nnohup bash ${scriptFile} > ${logFile} 2>&1 &`;

return [{ json: { command, logFile, scriptFile, totalItems: items.length, BATCH_HAS_UMI: batchHasUmi } }];

const out = ($json.stdout || '').trim();
const parts = out.split('|');
const rc = parts[0]; const umi = parts[1];
const src = $('Get Pending ICA DB').item.json;
const base = p => String(p).substring(String(p).lastIndexOf('/') + 1);
return {
  json: {
    dop_id: src.dop_id,
    SAMPLE_ID: src.sample_id,
    PROJECT_ID: src.project_id,
    Panel: src.panel,
    R1_PATH: src.r1_path,
    R2_PATH: src.r2_path,
    R1_NAME: base(src.r1_path),
    R2_NAME: base(src.r2_path),
    remote_count: parseInt(rc || '0', 10),
    HAS_UMI: (umi || 'false').trim()
  }
};

const items = $('Filter Not Uploaded DB').all().map(i => i.json);
const webhookUrl = 'http://10.20.0.30:5678/webhook/3883600a-ff60-4431-bcef-16e71ff99971';
const timestamp = Date.now();
const batchHasUmi = items.every(i => String(i.HAS_UMI).trim() === 'true');
const AWS_CONC = 32;
const dir = '/volume1/ALLDATA/Temp/ica_db_uploads';

// --- FFPE (HT) DNA+RNA birlestirme mantigi ---
// HT panelinde ornek adindaki -D / -R ekini at -> ayni Pair klasoru
const isHT = (it) => String(it.Panel).toUpperCase() === 'HT';
const pairIdOf = (it) => {
  const s = String(it.SAMPLE_ID);
  if (isHT(it) && /-[DR]$/.test(s)) return s.slice(0, -2);
  return s;
};
// Her HT pair'inin bu batch'teki uye sayisi -> webhook'u SADECE son uyede tetikle
const htPairCount = {};
items.forEach(it => { if (isHT(it)) { const p = pairIdOf(it); htPairCount[p] = (htPairCount[p] || 0) + 1; } });
const htPairSeen = {};

const sampleBlocks = items.map((item) => {
  const folder = pairIdOf(item);                 // HT -> pair id, ctDNA -> sample_id
  const files = [item.R1_PATH, item.R2_PATH].filter(Boolean);

  // webhook: ctDNA -> her zaman; HT -> sadece pair'in son parcasinda, pair adi + FFPE_v2 ile
  let fireWebhook = true;
  let whSampleId = item.SAMPLE_ID;
  let whPanel = item.Panel;
  if (isHT(item)) {
    htPairSeen[folder] = (htPairSeen[folder] || 0) + 1;
    fireWebhook = (htPairSeen[folder] === htPairCount[folder]);
    whSampleId = folder;
    whPanel = 'FFPE_v2';
  }

  const payload = Buffer.from(JSON.stringify({
    SAMPLE_ID: whSampleId,
    PROJECT_ID: item.PROJECT_ID,
    Panel: whPanel,
    HAS_UMI: String(item.HAS_UMI),
    BATCH_HAS_UMI: batchHasUmi
  })).toString('base64');

  const cpLines = files.map((f) => {
    const fileName = f.substring(f.lastIndexOf('/') + 1);
    return `  upload_one "${f}" "s3://$BUCKET/\${PREFIX}${folder}/${fileName}" & pids+=($!)`;
  }).join('\n');

  const okBlock = fireWebhook
    ? [
`  sleep 30`,
`  echo "[$(date '+%F %T')] webhook -> ${whSampleId}"`,
`  echo '${payload}' | base64 -d | curl -s -X POST "${webhookUrl}" -H "Content-Type: application/json" -d @- --max-time 30`,
      ].join('\n')
    : `  echo "[$(date '+%F %T')] upload ok ${item.SAMPLE_ID} - pair'in diger parcasi bekleniyor, webhook atlandi"`;

  return [
`echo "[$(date '+%F %T')] === ${item.SAMPLE_ID} START (folder: ${folder}) ==="`,
`CREDS=$("$ICAV2" projectdata temporarycredentials /input_folder/ --project-id "${item.PROJECT_ID}" -o json)`,
`AK=$(echo "$CREDS" | jq -r .awsTempCredentials.accessKey)`,
`SK=$(echo "$CREDS" | jq -r .awsTempCredentials.secretKey)`,
`ST=$(echo "$CREDS" | jq -r .awsTempCredentials.sessionToken)`,
`BUCKET=$(echo "$CREDS" | jq -r .awsTempCredentials.bucket)`,
`PREFIX=$(echo "$CREDS" | jq -r .awsTempCredentials.objectPrefix)`,
`WD=$(mktemp -d -p ${dir})`,
`echo '[awsup]' > "$WD/creds"`,
`echo "aws_access_key_id=$AK" >> "$WD/creds"`,
`echo "aws_secret_access_key=$SK" >> "$WD/creds"`,
`echo "aws_session_token=$ST" >> "$WD/creds"`,
`echo '[profile awsup]' > "$WD/config"`,
`echo 'region=us-east-1' >> "$WD/config"`,
`echo 's3=' >> "$WD/config"`,
`echo '    max_concurrent_requests=${AWS_CONC}' >> "$WD/config"`,
`echo '    multipart_threshold=64MB' >> "$WD/config"`,
`echo '    multipart_chunksize=16MB' >> "$WD/config"`,
`export AWS_SHARED_CREDENTIALS_FILE="$WD/creds" AWS_CONFIG_FILE="$WD/config"`,
`pids=()`,
cpLines,
`ok=1; for p in "\${pids[@]}"; do wait $p || ok=0; done`,
`unset AWS_SHARED_CREDENTIALS_FILE AWS_CONFIG_FILE; rm -rf "$WD"`,
`if [ "$ok" = "1" ]; then`,
okBlock,
`else`,
`  echo "[$(date '+%F %T')] UPLOAD FAILED ${item.SAMPLE_ID} - webhook skipped"`,
`fi`,
  ].join('\n');
}).join('\n');

const scriptFile = `${dir}/upload_${timestamp}.sh`;
const logFile = `${dir}/upload_${timestamp}.log`;

const script = [
`#!/bin/bash`,
`AWS=/volume1/ALLDATA/bios/aws/dist/aws`,
`ICAV2=/volume1/ALLDATA/bios/illumina/icav2`,
`upload_one(){ src="$1"; dst="$2"; for a in 1 2 3; do "$AWS" s3 cp "$src" "$dst" --profile awsup && return 0; echo "retry $a: $src"; sleep $((a*10)); done; return 1; }`,
sampleBlocks,
`echo "[$(date '+%F %T')] ALL DONE"`,
].join('\n');

const command = `mkdir -p ${dir} && cat > ${scriptFile} <<'AWSEOF'\n${script}\nAWSEOF\nnohup bash ${scriptFile} > ${logFile} 2>&1 &`;

return [{ json: { command, logFile, scriptFile, totalItems: items.length, BATCH_HAS_UMI: batchHasUmi } }];
